use super::*;
fn parts(chapter:&str)->ManuscriptParts{ManuscriptParts{schema_version:1,parts:vec![ManuscriptPart{id:"part-a".into(),title:"الجزء 明 e\u{301} 👩🏽‍🚀 𠀀 \u{e000}".into(),hidden:false},ManuscriptPart{id:"part-b".into(),title:"Second".into(),hidden:true}],chapters:vec![ChapterPart{chapter_id:chapter.into(),part_id:"part-a".into()}]}}
async fn fixture()->(tempfile::TempDir,Storage,crate::NovelCreated){let dir=tempfile::tempdir().unwrap();let store=Storage::open(&dir.path().join("parts.sqlite")).await.unwrap();let novel=store.create_novel("Parts fixture").await.unwrap();(dir,store,novel)}
#[tokio::test]async fn explicit_parts_save_keeps_canonical_order_rich_writing_and_unrelated_planning_exact(){let (_dir,store,novel)=fixture().await;store.create_chapter(&novel.project.id,"第二章 مِ").await.unwrap();let original=store.sync_manifest(&novel.project.id).await.unwrap();let unrelated=json!({"schemaVersion":1,"records":[],"events":[],"privateExtension":{"exact":"مِ e\u{301} 👩🏽‍🚀 𠀀 \u{e000}"}});store.save_project_data(&novel.project.id,"planning",unrelated.clone(),None).await.unwrap();let snapshot=store.parts_edit_snapshot(&novel.project.id).await.unwrap();let model=parts(&novel.scene.chapter_id);let saved=store.save_manuscript_parts_checked(snapshot.clone(),model.clone()).await.unwrap();assert_eq!(saved.planning.as_ref().unwrap().payload["manuscriptParts"],serde_json::to_value(&model).unwrap());for (key,value) in unrelated.as_object().unwrap(){assert_eq!(&saved.planning.as_ref().unwrap().payload[key],value);}assert_eq!(store.sync_manifest(&novel.project.id).await.unwrap(),original);assert_eq!(saved.project_source,snapshot.project_source);assert_eq!(saved.chapter_sources,snapshot.chapter_sources);assert_ne!(saved.planning.as_ref().unwrap().revision_id,snapshot.planning.as_ref().unwrap().revision_id);let cursor=store.sync_cursor().await.unwrap();assert_eq!(store.save_manuscript_parts_checked(saved.clone(),model).await.unwrap(),saved);assert_eq!(store.sync_cursor().await.unwrap(),cursor);}
#[tokio::test]async fn stale_chapter_project_or_planning_capture_refuses_without_partial_revisions(){for defect in ["chapter","project","planning"]{let (_dir,store,novel)=fixture().await;let snapshot=store.parts_edit_snapshot(&novel.project.id).await.unwrap();match defect{"chapter"=>store.rename_chapter(&novel.scene.chapter_id,"Changed chapter").await.unwrap(),"project"=>{store.create_chapter(&novel.project.id,"Added chapter").await.unwrap();},_=>{store.save_project_data(&novel.project.id,"planning",json!({"schemaVersion":1,"records":[]}),None).await.unwrap();}}let marker=store.sync_cursor().await.unwrap();assert!(store.save_manuscript_parts_checked(snapshot,parts(&novel.scene.chapter_id)).await.unwrap_err().contains("changed"),"{defect}");assert_eq!(store.sync_cursor().await.unwrap(),marker);assert!(store.load_project_data(&novel.project.id,"planning").await.unwrap().is_none_or(|p|p.payload.get("manuscriptParts").is_none()));}}
#[tokio::test]async fn ordinary_scene_typing_does_not_stale_unrelated_part_assignment(){let (_dir,store,novel)=fixture().await;let capture=store.parts_edit_snapshot(&novel.project.id).await.unwrap();let mut scene=novel.scene.scene.clone();scene.document=json!({"type":"doc","content":[{"type":"paragraph","attrs":{"dir":"rtl","lang":"ar"},"content":[{"type":"text","text":"مِ 中文 e\u{301} 👩🏽‍🚀 𠀀 \u{e000}","marks":[{"type":"bold"},{"type":"underline"}]}]}]});let saved=store.save_scene(&novel.scene.id,scene,Some(novel.scene.revision_id)).await.unwrap();store.save_manuscript_parts_checked(capture,parts(&novel.scene.chapter_id)).await.unwrap();assert_eq!(store.load_scene(&novel.scene.id).await.unwrap(),saved);}
#[tokio::test]async fn missing_foreign_or_conflicted_chapter_assignments_fail_all_save_paths(){let (_dir,store,novel)=fixture().await;let other=store.create_novel("Other").await.unwrap();for chapter in ["missing",other.scene.chapter_id.as_str()]{let candidate=json!({"schemaVersion":1,"manuscriptParts":parts(chapter)});let marker=store.sync_cursor().await.unwrap();assert!(store.save_project_data(&novel.project.id,"planning",candidate.clone(),None).await.is_err());assert!(store.save_project_data_checked(&novel.project.id,"planning",candidate.clone(),None,&[]).await.is_err());let snapshot=store.parts_edit_snapshot(&novel.project.id).await.unwrap();assert!(store.save_manuscript_parts_checked(snapshot,parts(chapter)).await.is_err());assert_eq!(store.sync_cursor().await.unwrap(),marker);}
    let snapshot=store.parts_edit_snapshot(&novel.project.id).await.unwrap();let mut tx=store.pool.begin().await.unwrap();append(&mut tx,&novel.project.id,&novel.scene.chapter_id,"chapter",vec![],json!({"title":"Competing chapter","order":[novel.scene.id]}),"create",&id()).await.unwrap();tx.commit().await.unwrap();let marker=store.sync_cursor().await.unwrap();assert!(store.parts_edit_snapshot(&novel.project.id).await.is_err());assert!(store.save_manuscript_parts_checked(snapshot,parts(&novel.scene.chapter_id)).await.is_err());assert!(store.save_project_data(&novel.project.id,"planning",json!({"schemaVersion":1,"manuscriptParts":parts(&novel.scene.chapter_id)}),None).await.is_err());assert_eq!(store.sync_cursor().await.unwrap(),marker);}
#[tokio::test]async fn generic_resolution_cannot_invent_foreign_assignments_but_acknowledged_stale_history_remains(){let (_dir,store,novel)=fixture().await;let other=store.create_novel("Other").await.unwrap();let first=store.save_project_data(&novel.project.id,"planning",json!({"schemaVersion":1,"records":[]}),None).await.unwrap();let entity=format!("{}:planning",novel.project.id);let historical=json!({"schemaVersion":1,"records":[],"manuscriptParts":parts("historical-missing-chapter")});let historical_id=id();let mut tx=store.pool.begin().await.unwrap();append(&mut tx,&novel.project.id,&entity,"projectData",vec![],historical.clone(),"planning",&historical_id).await.unwrap();tx.commit().await.unwrap();let heads=vec![first.revision_id.clone(),historical_id];let marker=store.sync_cursor().await.unwrap();assert!(store.resolve_project_data(&novel.project.id,"planning",json!({"schemaVersion":1,"records":[],"manuscriptParts":parts(&other.scene.chapter_id)}),heads.clone()).await.is_err());assert_eq!(store.sync_cursor().await.unwrap(),marker);let recovered=store.resolve_project_data(&novel.project.id,"planning",historical.clone(),heads).await.unwrap();assert_eq!(recovered.payload,historical);let mut unrelated=historical;unrelated["privateExtension"]=json!("Unrelated edit مِ");let saved=store.save_project_data(&novel.project.id,"planning",unrelated.clone(),Some(recovered.revision_id)).await.unwrap();assert_eq!(saved.payload,unrelated);let capture=store.parts_edit_snapshot(&novel.project.id).await.unwrap();let mut model=parts("historical-missing-chapter");model.parts[0].title="Renamed retained group".into();assert!(store.save_manuscript_parts_checked(capture,model).await.is_ok());}
#[test]fn parts_schema_rejects_duplicates_unknown_fields_and_dangling_groups(){let mut candidate=parts("chapter");candidate.parts.push(candidate.parts[0].clone());assert!(candidate.validate().is_err());let mut candidate=parts("chapter");candidate.chapters.push(candidate.chapters[0].clone());assert!(candidate.validate().is_err());let mut candidate=parts("chapter");candidate.chapters[0].part_id="missing".into();assert!(candidate.validate().is_err());assert!(ManuscriptParts::from_planning(&json!({"manuscriptParts":{"schemaVersion":1,"parts":[],"chapters":[],"extra":true}})).is_err());assert_eq!(ManuscriptParts::from_planning(&json!({"schemaVersion":1,"legacy":"unchanged"})).unwrap(),ManuscriptParts::default());}
#[tokio::test]async fn failed_parts_head_commit_rolls_back_revision_and_marker(){let (_dir,store,novel)=fixture().await;let capture=store.parts_edit_snapshot(&novel.project.id).await.unwrap();let marker=store.sync_cursor().await.unwrap();sqlx::query("CREATE TRIGGER reject_parts_head BEFORE INSERT ON project_data WHEN NEW.kind='planning' BEGIN SELECT RAISE(ABORT,'Synthetic Parts head failure'); END;").execute(&store.pool).await.unwrap();assert!(store.save_manuscript_parts_checked(capture.clone(),parts(&novel.scene.chapter_id)).await.unwrap_err().contains("Synthetic Parts"));assert_eq!(store.sync_cursor().await.unwrap(),marker);assert_eq!(store.parts_edit_snapshot(&novel.project.id).await.unwrap(),capture);assert!(store.load_project_data(&novel.project.id,"planning").await.unwrap().is_none());}
#[tokio::test]async fn malformed_or_oversized_retained_metadata_refuses_before_parts_projection(){let (_dir,store,novel)=fixture().await;let snapshot=store.parts_edit_snapshot(&novel.project.id).await.unwrap();let rid=snapshot.chapter_sources[0].revision_id.clone();sqlx::query("DROP TRIGGER immutable_revision_update").execute(&store.pool).await.unwrap();let malformed=json!({"title":"Untitled stale metadata","order":[novel.scene.id]});sqlx::query("UPDATE revision_envelope SET payload=?,checksum=? WHERE id=?").bind(malformed.to_string()).bind(hash(malformed.to_string().as_bytes())).bind(&rid).execute(&store.pool).await.unwrap();assert!(store.parts_edit_snapshot(&novel.project.id).await.unwrap_err().contains("differs"));sqlx::query("UPDATE revision_envelope SET payload=json_object('title','Chapter 1','padding',replace(hex(zeroblob(8500000)),'00','x')) WHERE id=?").bind(&rid).execute(&store.pool).await.unwrap();assert!(store.parts_edit_snapshot(&novel.project.id).await.unwrap_err().contains("byte limit"));}

#[tokio::test]
async fn parts_archive_and_branch_roundtrips_remap_chapters_retain_history_and_allow_checked_save(){
    let (_dir,store,novel)=fixture().await;
    let second=store.create_chapter(&novel.project.id,"第二章 مِ").await.unwrap();
    let mut rich=novel.scene.scene.clone();
    rich.document=json!({"type":"doc","content":[{"type":"paragraph","attrs":{"dir":"rtl","lang":"ar","lineSpacing":1.5},"content":[{"type":"text","text":"مِ 中文 e\u{301} 👩🏽‍🚀 𠀀 \u{e000}","marks":[{"type":"bold"},{"type":"italic"},{"type":"underline"}]}]},{"type":"paragraph","attrs":{"dir":"ltr","lang":"zh-Hans"},"content":[{"type":"text","text":"中文 𠀀 e\u{301}"}]}]});
    let written=store.save_scene(&novel.scene.id,rich.clone(),Some(novel.scene.revision_id.clone())).await.unwrap();
    let initial_parts=parts(&novel.scene.chapter_id);
    let first=store.save_manuscript_parts_checked(store.parts_edit_snapshot(&novel.project.id).await.unwrap(),initial_parts.clone()).await.unwrap();
    let mut current_parts=initial_parts.clone();current_parts.parts.reverse();current_parts.parts[0].hidden=false;current_parts.parts[1].hidden=true;current_parts.parts[1].title="الجزء المعدّل 明 e\u{301} 👩🏽‍🚀 𠀀 \u{e000}".into();current_parts.chapters.push(ChapterPart{chapter_id:second.id.clone(),part_id:"part-b".into()});
    store.save_manuscript_parts_checked(first,current_parts.clone()).await.unwrap();
    let canonical=store.open_project(&novel.project.id).await.unwrap();
    let source_scene_history=store.history(&novel.scene.id).await.unwrap();
    let archive=store.export_archive(&novel.project.id).await.unwrap();
    for operation in ["archive","branch"]{
        let copied=if operation=="archive"{store.import_archive(&archive).await.unwrap()}else{let branch=store.create_project_branch(&novel.project.id,"Parts branch مِ 中文").await.unwrap();store.open_project(&branch.project_id).await.unwrap()};
        assert_ne!(copied.project.id,novel.project.id);
        assert_eq!(copied.chapters.iter().map(|c|(&c.title,c.position)).collect::<Vec<_>>(),canonical.chapters.iter().map(|c|(&c.title,c.position)).collect::<Vec<_>>());
        assert!(copied.chapters.iter().zip(&canonical.chapters).all(|(new,old)|new.id!=old.id&&new.project_id==copied.project.id));
        assert_eq!(copied.scenes[0].scene,rich);assert_ne!(copied.scenes[0].id,novel.scene.id);assert_eq!(copied.scenes[0].chapter_id,copied.chapters[0].id);
        assert_eq!(store.history(&copied.scenes[0].id).await.unwrap().iter().map(|r|r.payload.clone()).collect::<Vec<_>>(),source_scene_history.iter().map(|r|r.payload.clone()).collect::<Vec<_>>());
        let fresh=store.parts_edit_snapshot(&copied.project.id).await.unwrap();
        let mut expected=current_parts.clone();expected.chapters[0].chapter_id=copied.chapters[0].id.clone();expected.chapters[1].chapter_id=copied.chapters[1].id.clone();
        let copied_model=ManuscriptParts::from_planning(&fresh.planning.as_ref().unwrap().payload).unwrap();assert_eq!(copied_model,expected,"{operation}");
        let retained:Vec<String>=sqlx::query_scalar("SELECT payload FROM revision_envelope WHERE project_id=? AND entity_id=? AND entity_type='projectData' ORDER BY rowid").bind(&copied.project.id).bind(format!("{}:planning",copied.project.id)).fetch_all(&store.pool).await.unwrap();assert_eq!(retained.len(),2);
        let mut old_expected=initial_parts.clone();old_expected.chapters[0].chapter_id=copied.chapters[0].id.clone();let historical=retained.iter().map(|raw|ManuscriptParts::from_planning(&serde_json::from_str::<Value>(raw).unwrap()).unwrap()).collect::<Vec<_>>();assert!(historical.contains(&old_expected));assert!(historical.contains(&expected));assert!(historical.iter().flat_map(|p|&p.chapters).all(|a|copied.chapters.iter().any(|c|c.id==a.chapter_id)));
        let before_head=fresh.planning.as_ref().unwrap().revision_id.clone();let mut edited=copied_model;edited.parts[0].title=format!("{operation} owned Part مِ e\u{301}");let saved=store.save_manuscript_parts_checked(fresh,edited.clone()).await.unwrap();assert_ne!(saved.planning.as_ref().unwrap().revision_id,before_head);assert_eq!(ManuscriptParts::from_planning(&saved.planning.unwrap().payload).unwrap(),edited);assert_eq!(store.open_project(&copied.project.id).await.unwrap(),copied);
    }
    assert_eq!(store.load_scene(&novel.scene.id).await.unwrap(),written);assert_eq!(store.open_project(&novel.project.id).await.unwrap(),canonical);assert_eq!(ManuscriptParts::from_planning(&store.load_project_data(&novel.project.id,"planning").await.unwrap().unwrap().payload).unwrap(),current_parts);
}
